import {assert} from 'chai';
import {afterEach, beforeEach, it} from 'mocha';

import {assertScreenshot, doubleRaf, raf, renderElementIntoDOM} from '../../../../testing/DOMHelpers.js';
import {describeWithEnvironment} from '../../../../testing/EnvironmentHelpers.js';
import * as UI from '../../legacy.js';
import * as ObjectUI from '../object_ui/object_ui.js';

import * as SourceFrame from './source_frame.js';

describeWithEnvironment('JSONView', () => {
  const cleanHighlights = () => {
    CSS.highlights.get('highlighted-search-result')?.clear();
    CSS.highlights.get('current-search-result')?.clear();
  };
  beforeEach(cleanHighlights);
  afterEach(cleanHighlights);

  it('instantiates a read-only ObjectPropertiesSection', async () => {
    const parsedJSON = new SourceFrame.JSONView.ParsedJSON({foo: 'bar'}, '', '');
    const jsonView = new SourceFrame.JSONView.JSONView(parsedJSON);
    renderElementIntoDOM(jsonView);
    await UI.Widget.Widget.allUpdatesComplete;

    const widgetElement = jsonView.contentElement.querySelector('devtools-widget');
    assert.exists(widgetElement);
    const widget = UI.Widget.Widget.get(widgetElement);
    assert.instanceOf(widget, ObjectUI.ObjectPropertiesSection.ObjectPropertiesSectionWidget);
    assert.isTrue(widget.objectTree?.readOnly);
    jsonView.detach();
  });

  it('handles search correctly', async () => {
    const parsedJSON = new SourceFrame.JSONView.ParsedJSON({foo: 'bar', baz: 'qux'}, '', '');
    const jsonView = new SourceFrame.JSONView.JSONView(parsedJSON, true);
    const searchableView = new UI.SearchableView.SearchableView(jsonView, null);
    jsonView.setSearchableView(searchableView);
    renderElementIntoDOM(jsonView);
    await raf();

    const treeView = jsonView.contentElement.querySelector<UI.TreeOutline.TreeViewElement>('devtools-tree');
    assert.exists(treeView);
    const treeOutline = treeView.getInternalTreeOutlineForTest();
    assert.exists(treeOutline);

    const rootElement = treeOutline.rootElement().childAt(0);
    assert.exists(rootElement);
    await raf();

    const searchConfig = new UI.SearchableView.SearchConfig('ba', false, false, false);
    await jsonView.performSearch(searchConfig, true);
    await doubleRaf();

    const shadowRoot = treeView.shadowRoot;
    assert.exists(shadowRoot);

    let highlightedMatches = CSS.highlights.get('highlighted-search-result');
    let currentMatches = CSS.highlights.get('current-search-result');
    assert.strictEqual((highlightedMatches?.size ?? 0) + (currentMatches?.size ?? 0), 2);
    assert.strictEqual(currentMatches?.size, 1);
    assert.exists(currentMatches);
    const currentRange = Array.from(currentMatches.values())[0];
    assert.strictEqual(currentRange?.toString(), 'ba');

    // Jump to next match
    jsonView.jumpToNextSearchResult();
    await doubleRaf();
    highlightedMatches = CSS.highlights.get('highlighted-search-result');
    currentMatches = CSS.highlights.get('current-search-result');
    assert.strictEqual((highlightedMatches?.size ?? 0) + (currentMatches?.size ?? 0), 2);
    assert.strictEqual(currentMatches?.size, 1);

    // Cancel search
    jsonView.onSearchCanceled();
    await doubleRaf();
    highlightedMatches = CSS.highlights.get('highlighted-search-result');
    assert.strictEqual(highlightedMatches?.size ?? 0, 0);
    currentMatches = CSS.highlights.get('current-search-result');
    assert.strictEqual(currentMatches?.size ?? 0, 0);
  });

  it('cancels search when new parsedJSON is set', async () => {
    const parsedJSON = new SourceFrame.JSONView.ParsedJSON({foo: 'bar', baz: 'qux'}, '', '');
    const jsonView = new SourceFrame.JSONView.JSONView(parsedJSON, true);
    const searchableView = new UI.SearchableView.SearchableView(jsonView, null);
    jsonView.setSearchableView(searchableView);
    renderElementIntoDOM(jsonView);
    await raf();

    const searchConfig = new UI.SearchableView.SearchConfig('ba', false, false, false);
    await jsonView.performSearch(searchConfig, true);
    await doubleRaf();

    let currentMatches = CSS.highlights.get('current-search-result');
    assert.strictEqual(currentMatches?.size, 1);

    jsonView.parsedJSON = new SourceFrame.JSONView.ParsedJSON({other: 'data'}, '', '');
    await raf();

    currentMatches = CSS.highlights.get('current-search-result');
    assert.strictEqual(currentMatches?.size ?? 0, 0);
  });

  it('finds nested keys and values inside collapsed JSON branches and expands ancestors on jump', async () => {
    const parsed = await SourceFrame.JSONView.JSONView.parseJSON('{"outer":{"inner":{"needle":"found-value"}}}');
    assert.isNotNull(parsed);
    const jsonView = new SourceFrame.JSONView.JSONView(parsed, true);
    const searchableView = new UI.SearchableView.SearchableView(jsonView, null);
    jsonView.setSearchableView(searchableView);
    renderElementIntoDOM(jsonView);
    await raf();

    await jsonView.performSearch(new UI.SearchableView.SearchConfig('found-value', false, false, false), true);
    await doubleRaf();

    const treeView = jsonView.contentElement.querySelector<UI.TreeOutline.TreeViewElement>('devtools-tree');
    assert.exists(treeView?.shadowRoot);
    assert.include(treeView.shadowRoot.textContent ?? '', 'needle');
    const currentMatches = CSS.highlights.get('current-search-result');
    assert.strictEqual(currentMatches?.size, 1);
    assert.exists(currentMatches);
    assert.strictEqual(Array.from(currentMatches.values())[0]?.toString(), 'found-value');
  });

  it('matches property paths such as items[1].id or items.1.id', async () => {
    const parsed = await SourceFrame.JSONView.JSONView.parseJSON('{"items":[{"id":"first"},{"id":"target"}]}');
    assert.isNotNull(parsed);
    const jsonView = new SourceFrame.JSONView.JSONView(parsed, true);
    const searchableView = new UI.SearchableView.SearchableView(jsonView, null);
    jsonView.setSearchableView(searchableView);
    renderElementIntoDOM(jsonView);
    await raf();

    await jsonView.performSearch(new UI.SearchableView.SearchConfig('items[1].id', false, false, false), true);
    await doubleRaf();

    const treeView = jsonView.contentElement.querySelector<UI.TreeOutline.TreeViewElement>('devtools-tree');
    assert.exists(treeView?.shadowRoot);
    assert.include(treeView.shadowRoot.textContent ?? '', 'target');
    let highlightedMatches = CSS.highlights.get('highlighted-search-result');
    let currentMatches = CSS.highlights.get('current-search-result');
    assert.strictEqual((highlightedMatches?.size ?? 0) + (currentMatches?.size ?? 0), 1);
    assert.strictEqual(currentMatches?.size, 1);
    assert.exists(currentMatches);
    assert.strictEqual(Array.from(currentMatches.values())[0]?.toString(), 'id');

    await jsonView.performSearch(new UI.SearchableView.SearchConfig('items.1.id', false, false, false), true);
    await doubleRaf();

    highlightedMatches = CSS.highlights.get('highlighted-search-result');
    currentMatches = CSS.highlights.get('current-search-result');
    assert.strictEqual((highlightedMatches?.size ?? 0) + (currentMatches?.size ?? 0), 1);
    assert.strictEqual(currentMatches?.size, 1);
    assert.exists(currentMatches);
    assert.strictEqual(Array.from(currentMatches.values())[0]?.toString(), 'id');

    await jsonView.performSearch(new UI.SearchableView.SearchConfig('items', false, false, false), true);
    await doubleRaf();

    highlightedMatches = CSS.highlights.get('highlighted-search-result');
    currentMatches = CSS.highlights.get('current-search-result');
    assert.strictEqual((highlightedMatches?.size ?? 0) + (currentMatches?.size ?? 0), 1);
  });

  it('auto-expands single-child wrapper chains and small levels within the row budget when startCollapsed is false',
     async () => {
       const parsed =
           await SourceFrame.JSONView.JSONView.parseJSON('{"data":{"viewer":{"user":{"id":42,"name":"Ada"}}}}');
       assert.isNotNull(parsed);
       const jsonView = new SourceFrame.JSONView.JSONView(parsed);
       renderElementIntoDOM(jsonView);
       await UI.Widget.Widget.allUpdatesComplete;
       await doubleRaf();

       const treeView = jsonView.contentElement.querySelector<UI.TreeOutline.TreeViewElement>('devtools-tree');
       assert.exists(treeView);
       // Collapsed children may still be populated and present in the DOM, so check the expansion state instead of text.
       const findChild = (parent: UI.TreeOutline.TreeElement, name: string): UI.TreeOutline.TreeElement|undefined =>
           parent.children().find(c => c.listItemElement.dataset.objectPropertyNameForTest === name);
       const root = treeView.getInternalTreeOutlineForTest().firstChild();
       assert.exists(root);
       assert.isTrue(root.expanded);
       const data = findChild(root, 'data');
       assert.exists(data);
       assert.isTrue(data.expanded);
       const viewer = findChild(data, 'viewer');
       assert.exists(viewer);
       assert.isTrue(viewer.expanded);
       const user = findChild(viewer, 'user');
       assert.exists(user);
       assert.isTrue(user.expanded);
       assert.exists(findChild(user, 'name'));
     });

  it('keeps levels collapsed when expanding them would exceed the auto-expand row budget', async () => {
    const items = Array.from({length: 35}, (_, i) => ({id: `item-${i}`}));
    const parsed = new SourceFrame.JSONView.ParsedJSON({items, meta: {page: 1, total: 35}}, '', '');
    const jsonView = new SourceFrame.JSONView.JSONView(parsed);
    renderElementIntoDOM(jsonView);
    await UI.Widget.Widget.allUpdatesComplete;
    await doubleRaf();

    const treeView = jsonView.contentElement.querySelector<UI.TreeOutline.TreeViewElement>('devtools-tree');
    assert.exists(treeView);
    // Collapsed children may still be populated and present in the DOM, so check the expansion state instead of text.
    const root = treeView.getInternalTreeOutlineForTest().firstChild();
    assert.exists(root);
    assert.isTrue(root.expanded);
    const itemsElement = root.children().find(c => c.listItemElement.dataset.objectPropertyNameForTest === 'items');
    const metaElement = root.children().find(c => c.listItemElement.dataset.objectPropertyNameForTest === 'meta');
    assert.exists(itemsElement);
    assert.exists(metaElement);
    assert.isFalse(itemsElement.expanded);
    assert.isFalse(metaElement.expanded);
  });

  it('renders visual baseline of JSONView', async () => {
    const parsedJSON = new SourceFrame.JSONView.ParsedJSON({
      stringField: 'hello world',
      numberField: 42,
      booleanField: true,
      nestedObject: {
        arrayField: [1, 2, 3],
      },
    },
                                                           'prefix_pre_', '_suffix_post');
    const jsonView = new SourceFrame.JSONView.JSONView(parsedJSON, true);
    renderElementIntoDOM(jsonView);
    await raf();

    const treeView = jsonView.contentElement.querySelector<UI.TreeOutline.TreeViewElement>('devtools-tree');
    assert.exists(treeView);
    const treeOutline = treeView.getInternalTreeOutlineForTest();
    assert.exists(treeOutline);
    const rootElement = treeOutline.rootElement().childAt(0);
    assert.exists(rootElement);
    await raf();
    rootElement.expand();
    await raf();

    await assertScreenshot('source_frame/json_view_baseline.png');
  });

  it('renders search highlights on JSONView', async () => {
    const parsedJSON = new SourceFrame.JSONView.ParsedJSON({
      baz: 'bar',
      foo: 'barbaz',
      bar: 'qux',
    },
                                                           '', '');
    const jsonView = new SourceFrame.JSONView.JSONView(parsedJSON, true);
    const searchableView = new UI.SearchableView.SearchableView(jsonView, null);
    jsonView.setSearchableView(searchableView);
    renderElementIntoDOM(jsonView);
    await raf();

    const treeView = jsonView.contentElement.querySelector<UI.TreeOutline.TreeViewElement>('devtools-tree');
    assert.exists(treeView);
    const treeOutline = treeView.getInternalTreeOutlineForTest();
    assert.exists(treeOutline);

    const rootElement = treeOutline.rootElement().childAt(0);
    assert.exists(rootElement);
    await raf();
    rootElement.expand();

    await raf();

    const searchConfig = new UI.SearchableView.SearchConfig('ba', false, false, false);
    await jsonView.performSearch(searchConfig, true);
    await doubleRaf();

    await assertScreenshot('source_frame/json_view_search_highlights.png');
  });
});
